<?php
require __DIR__.'/app/bootstrap.php';$u=require_login();$msg=$err=null;$id=(int)($_GET['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST')try{csrf_check();$a=$_POST['action']??'';if($a==='create'){$t=support_create_ticket((int)$u['id'],(string)$_POST['subject'],(string)$_POST['message'],(string)($_POST['department']??'general'),'normal',!empty($_POST['order_id'])?(int)$_POST['order_id']:null);header('Location: /support.php?id='.$t['id']);exit;}elseif($a==='reply'){ $t=operations_row('SELECT * FROM support_tickets WHERE id=? AND user_id=?',[(int)$_POST['id'],(int)$u['id']]);if(!$t)throw new RuntimeException('Ticket not found.');support_reply((int)$t['id'],(int)$u['id'],(string)$_POST['message'],false,false,'open');$msg='Reply sent.';}}catch(Throwable $e){$err=$e->getMessage();}
$ticket=$id?operations_row('SELECT * FROM support_tickets WHERE id=? AND user_id=?',[$id,(int)$u['id']]):null;$messages=$ticket?operations_rows('SELECT m.*,u.name FROM support_messages m LEFT JOIN users u ON u.id=m.user_id WHERE m.ticket_id=? AND m.is_internal=0 ORDER BY m.id',[$id]):[];$tickets=operations_rows('SELECT * FROM support_tickets WHERE user_id=? ORDER BY id DESC',[(int)$u['id']]);
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Support Center</title><link rel="stylesheet" href="/assets/shahkotpk-userdash-1.7.0.css"><link rel="stylesheet" href="/assets/operations-3.6.0.css"></head><body class="dashboard-page"><div class="dash-shell"><div class="dash-topbar"><a class="dash-back" href="/account.php">← My Account</a></div><section class="dash-hero"><div><span class="dash-badge">CUSTOMER CARE</span><h1>Support Center</h1><p>Orders, payments, seller and technical help with ticket history.</p></div></section><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><?php if($ticket):?><section class="dash-card"><h2><?=e($ticket['ticket_number'].' — '.$ticket['subject'])?></h2><?php foreach($messages as $m):?><div class="ops-card" style="margin:10px 0"><b><?=e($m['is_staff']?'ShahkotPK Support':($m['name']?:'You'))?></b><small style="float:right"><?=e($m['created_at'])?></small><p><?=nl2br(e($m['message']))?></p></div><?php endforeach;?><?php if(!in_array($ticket['status'],['resolved','closed'],true)):?><form method="post" class="ops-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="reply"><input type="hidden" name="id" value="<?=e($ticket['id'])?>"><textarea class="wide" name="message" placeholder="Your reply" required></textarea><button class="btn">Send Reply</button></form><?php endif;?></section><?php else:?><div class="ops-grid"><section class="ops-card"><h2>Open New Ticket</h2><form method="post" class="ops-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><select name="department"><option>general</option><option>orders</option><option>payments</option><option>seller</option><option>technical</option><option>verification</option><option>ads</option></select><input name="subject" placeholder="Subject" required><input name="order_id" type="number" placeholder="Order ID (optional)"><textarea class="wide" name="message" placeholder="How can we help?" required></textarea><button class="btn">Create Ticket</button></form></section><section class="ops-card"><h2>My Tickets</h2><?php foreach($tickets as $t):?><p><a href="/support.php?id=<?=e($t['id'])?>"><b><?=e($t['ticket_number'])?></b> <?=e($t['subject'])?></a><br><small><?=e($t['status'].' · '.$t['last_message_at'])?></small></p><?php endforeach;?></section></div><?php endif;?></div></body></html>
